        add.s64         %rd9, %rd8, %rd24;      // sh_sumsq[tid + 1]
        ld.shared.f32   %f7, [%rd9];
        add.f32         %f6, %f6, %f7;
        st.shared.f32   [%rd5], %f6;
L2_skip1:
    bar.sync 0;
    // Thread 0 computes invstd from sum of squared diffs
    setp.eq.u32     %p2, %r0, 0;
    @!%p2 bra       L_after_invstd;
        ld.shared.f32   %f18, [sh_sumsq];
        cvt.rn.f32.u32  %f10, %r20;        // N
        div.rn.f32      %f19, %f18, %f10;  // var
        add.f32         %f15, %f19, %f20;  // var + eps
        sqrt.rn.f32     %f16, %f15;        // sqrt(var + eps)
        rcp.rn.f32      %f17, %f16;        // invstd
        st.shared.f32   [sh_invstd], %f17;
L_after_invstd:
    bar.sync 0;
    // Load mean and invstd for all threads
    ld.shared.f32   %f30, [sh_mean];
    ld.shared.f32   %f31, [sh_invstd];
    // Phase 2: normalize and apply affine
    mov.u32         %r4, %r0;              // idx = tid
L_loop_norm:
    setp.ge.u32     %p3, %r4, %r20;
    @%p3 bra        L_done_norm;

    // offsets
     mul.wide.u32    %rd36, %r4, 4;             // idx*4
     add.s64         %rd40, %rd30, %rd36;       // in addr
     add.s64         %rd41, %rd31, %rd36;       // out addr
     add.s64         %rd42, %rd12, %rd36;       // gamma addr
     add.s64         %rd43, %rd13, %rd36;       // beta addr

    ld.global.f32   %f32, [%rd40];                 // x
    ld.global.f32   %f33, [%rd42];                 // gamma
    ld.global.f32   %f34, [%rd43];                 // beta

    sub.f32         %f35, %f32, %f30;              // x - mean
    mul.f32         %f36, %f35, %f31;              // (x - mean) * invstd
    mul.f32         %f37, %f36, %f33;              // * gamma
    add.f32         %f38, %f37, %f34;              // + beta

    st.global.f32   [%rd41], %f38;

    add.u32         %r4, %r4, %r1;
    bra             L_loop_norm;

L_done_norm:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("layernorm_affine")

class ModelNew(nn.Module):
    def __init__(self, normalized_shape: tuple):
        super().__init__()
        # Match the reference constructor and parameters exactly.
        self.normalized_shape = tuple(normalized_shape)
        numel = 1
        for d in self.normalized_shape:
            numel *= int(d)
        # Parameters match PyTorch LayerNorm defaults: weight=ones, bias=zeros, dtype=float32
        self.weight = nn.Parameter(torch.ones(self.normalized_shape, dtype=torch.float32))
        self.bias = nn.Parameter(torch.zeros(self.normalized_shape, dtype=torch.float32))
        self.eps = 1e-5

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be on CUDA device"
        assert x.dtype == torch.float32, "Only float32 is supported"
        assert x.is_contiguous(), "Input must be contiguous"
        assert tuple(x.shape[1:]) == self.normalized_shape, "Input shape must match normalized_shape"
        assert self.weight.shape == self.normalized_shape and self.bias.shape == self.normalized_shape
        assert self.weight.device == x.device and self.bias.device == x.device, "Parameters must be on same device as input"

        out = torch.empty_like(x)
        batch = x.shape[0]
        norm_size = 1
        for d in self.normalized_shape:
            norm_size *= int(d)

        module = _get_ptx_module()
        module.launch(
            "layernorm_affine",
            grid=(int(batch), 1, 1),
            block=(1024, 1, 1),
            arguments=[x, out, self.weight, self.bias, i32(norm_size), i32(batch), f32(self.eps)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out
